// 反例组：alg:none 攻击 + 算法混淆（RS256 -> HS256）—— 安全实现必须拒绝
const crypto = require('crypto');

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function b64urlDecodeToBuffer(s) {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  return Buffer.from(s.replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64');
}
function hmac(secret, data) { return crypto.createHmac('sha256', secret).update(data).digest(); }
function eq(a, b) { return a.length === b.length && crypto.timingSafeEqual(a, b); }

// 安全的验签器：alg 固定为 RS256（非对称），绝不接受 HS256/none
function secureVerify(token, publicKey) {
  const parts = token.split('.');
  if (parts.length !== 3) return { ok: false, reason: 'malformed' };
  const header = JSON.parse(b64urlDecodeToBuffer(parts[0]).toString('utf8'));
  if (header.alg !== 'RS256') return { ok: false, reason: 'alg-pinned-reject' };
  return { ok: true, reason: 'would-verify-with-public-key' };   // 真实项目在此用 RSA 验签
}
// 有漏洞的验签器：直接信任 token 头里的 alg，且用同一把 key 做 HMAC
function vulnerableVerify(token, key) {
  const [h, p, s] = token.split('.');
  return eq(hmac(key, h + '.' + p), b64urlDecodeToBuffer(s));
}

const PUBLIC_KEY = '-----BEGIN PUBLIC KEY-----FAKE-RSA-PUBLIC-KEY-----END PUBLIC KEY-----';

// 攻击 1：alg:none —— 去掉签名
const noneHeader = b64urlEncode(JSON.stringify({ alg: 'none', typ: 'JWT' }));
const body = b64urlEncode(JSON.stringify({ sub: 'u1', role: 'admin' }));
const algNoneToken = noneHeader + '.' + body + '.';
console.log('alg_none_secure=' + secureVerify(algNoneToken, PUBLIC_KEY).reason);
// 朴素实现（alg 为 none 就放行）会被打穿
const naive = (t) => JSON.parse(b64urlDecodeToBuffer(t.split('.')[0]).toString('utf8')).alg === 'none';
console.log('alg_none_naive_accepts=' + naive(algNoneToken));

// 攻击 2：算法混淆 —— 攻击者用「公钥字符串」当 HMAC 密钥签一个 alg=HS256 的 token
const forgeHeader = b64urlEncode(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
const forgeForged = (() => {
  const si = forgeHeader + '.' + body;
  return si + '.' + b64urlEncode(hmac(PUBLIC_KEY, si));
})();
console.log('confusion_secure_reason=' + secureVerify(forgeForged, PUBLIC_KEY).reason);
console.log('confusion_vulnerable_accepts=' + vulnerableVerify(forgeForged, PUBLIC_KEY));
// 安全实现把 alg 钉死为 RS256，混淆 token 在第一步就被拒
console.log('pinned_alg_blocks_confusion=' + (secureVerify(forgeForged, PUBLIC_KEY).ok === false));
